  const chips=[['all',`Toutes (${js.length})`,null],['me',`Pour moi (${js.filter(({j})=>forMe(j)).length})`,null],...ORDER.map(s=>[s,`${STATUS[s].label} (${counts[s]||0})`,STATUS[s].color]),['fils',`Fils : inversion (${inv})`,'#d03b3b']];
